import { SLOT_API_RESPONSE_TYPE, SlotApiBetDetailRequest, SlotApiBetDetailResponse, SlotApiBetHistoryRequest, SlotApiBetHistoryResponse, SlotApiFrame, SlotApiGameInfoResponse, SlotApiGameStateResponse, SlotApiGetGameRequest, SlotApiGetGameResponse, SlotApiJackpotPoolRequest, SlotApiJackpotPoolSnapshot, SlotApiJackpotUnsubscribeResponse, SlotApiRequestType, SlotApiSpinResponse } from './SlotApiTypes';

export interface SlotWebSocketClientOptions {
    url?: string;
    token?: string;
    requestTimeoutMs?: number;
    heartbeatIntervalMs?: number;
    /** 斷線時是否自動用token重連 */
    autoReconnect?: boolean;
    /** 重連延遲 */
    reconnectDelayMs?: number;
    /** 自動重連次數 預設 5 */
    maxReconnectAttempts?: number;
}

type SlotApiFrameListener = (frame: SlotApiFrame) => void;
type PendingRequest = {
    resolve: (frame: SlotApiFrame<any>) => void;
    reject: (error: Error) => void;
    timeoutId: ReturnType<typeof setTimeout>;
};

const DEFAULT_WS_URL = 'ws://localhost:8500/ws';

export function getSlotApiTokenFromUrl(): string {
    if (typeof globalThis.location === 'undefined') return '';
    try {
        const params = new URL(globalThis.location.href).searchParams;
        return params.get('token') ?? params.get('auth') ?? '';
    } catch {
        return '';
    }
}

export function buildSlotApiWebSocketUrl(url: string = DEFAULT_WS_URL, token: string = getSlotApiTokenFromUrl()): string {
    if (!token) return url;
    try {
        const base = typeof globalThis.location === 'undefined' ? 'ws://localhost' : globalThis.location.href.replace(/^http/, 'ws');
        const parsed = new URL(url, base);
        if (!parsed.searchParams.has('token')) parsed.searchParams.set('token', token);
        return parsed.toString();
    } catch {
        return url;
    }
}

export default class SlotWebSocketClient {
    private socket: WebSocket | null = null;
    private openPromise: Promise<void> | null = null;
    private pending = new Map<string, PendingRequest>();
    private listeners = new Set<SlotApiFrameListener>();
    private heartbeatId: ReturnType<typeof setInterval> | null = null;
    private readonly url: string;
    private readonly requestTimeoutMs: number;
    private readonly heartbeatIntervalMs: number;
    private readonly autoReconnect: boolean;
    private readonly reconnectDelayMs: number;
    private readonly maxReconnectAttempts: number;
    private reconnectAttempts = 0;
    private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
    private explicitClose = false;
    private readonly reconnectListeners = new Set<() => void>();

    constructor(options: SlotWebSocketClientOptions = {}) {
        this.url = buildSlotApiWebSocketUrl(options.url ?? DEFAULT_WS_URL, options.token);
        this.requestTimeoutMs = options.requestTimeoutMs ?? 10000;
        this.heartbeatIntervalMs = options.heartbeatIntervalMs ?? 25000;
        this.autoReconnect = options.autoReconnect ?? true;
        this.reconnectDelayMs = options.reconnectDelayMs ?? 1000;
        this.maxReconnectAttempts = options.maxReconnectAttempts ?? 5;
    }

    get isOpen(): boolean {
        return this.socket?.readyState === WebSocket.OPEN;
    }

    connect(): Promise<void> {
        this.explicitClose = false;
        this.clearReconnectTimer();
        if (this.isOpen) return Promise.resolve();
        if (this.openPromise) return this.openPromise;

        this.socket = new WebSocket(this.url);
        this.openPromise = new Promise<void>((resolve, reject) => {
            let settled = false;
            const socket = this.socket!;
            socket.onopen = () => {
                const wasReconnect = this.reconnectAttempts > 0;
                settled = true;
                this.openPromise = null;
                this.reconnectAttempts = 0;
                this.startHeartbeat();
                resolve();
                if (wasReconnect) for (const listener of this.reconnectListeners) listener();
            };
            socket.onmessage = (event: MessageEvent) => this.handleMessage(event.data);
            socket.onerror = () => {
                if (!settled) {
                    settled = true;
                    this.openPromise = null;
                    reject(new Error('slot websocket connect failed'));
                }
            };
            socket.onclose = () => {
                this.stopHeartbeat();
                this.rejectPending('slot websocket closed');
                if (!settled) {
                    settled = true;
                    this.openPromise = null;
                    reject(new Error('slot websocket closed before open'));
                }
                this.scheduleReconnect();
            };
        });

        return this.openPromise;
    }

    close(): void {
        this.explicitClose = true;
        this.clearReconnectTimer();
        this.stopHeartbeat();
        this.rejectPending('slot websocket closed');
        this.socket?.close();
        this.socket = null;
        this.openPromise = null;
    }

    onFrame(listener: SlotApiFrameListener): () => void {
        this.listeners.add(listener);
        return () => this.listeners.delete(listener);
    }

    /**
     * 斷線重連成功後觸發
     * 重送 GET_GAME_STATE 更新餘額 下注設定
     */
    onReconnect(listener: () => void): () => void {
        this.reconnectListeners.add(listener);
        return () => this.reconnectListeners.delete(listener);
    }

    private scheduleReconnect(): void {
        if (this.explicitClose || !this.autoReconnect) return;
        if (this.reconnectAttempts >= this.maxReconnectAttempts) {
            console.error('[SlotWSClient] reconnect attempts exhausted', this.reconnectAttempts);
            return;
        }
        this.reconnectAttempts += 1;
        const delay = this.reconnectDelayMs * this.reconnectAttempts;
        this.clearReconnectTimer();
        this.reconnectTimer = setTimeout(() => {
            console.log('[SlotWSClient] reconnecting', { attempt: this.reconnectAttempts });
            this.connect().catch((error) => console.error('[SlotWSClient] reconnect failed', error));
        }, delay);
    }

    private clearReconnectTimer(): void {
        if (!this.reconnectTimer) return;
        clearTimeout(this.reconnectTimer);
        this.reconnectTimer = null;
    }

    async ping(correlationId: string = this.createCorrelationId('PING')): Promise<void> {
        await this.request('PING', undefined, correlationId);
    }

    async getGame(gameCode: string): Promise<SlotApiGetGameResponse> {
        const payload: SlotApiGetGameRequest = { game_code: gameCode };
        const frame = await this.request<SlotApiGetGameResponse>('SLOT_GET_GAME', payload);
        return frame.payload!;
    }

    async getGameInfo(gameCode: string, currency: string = 'TWD'): Promise<SlotApiGameInfoResponse> {
        const frame = await this.request<SlotApiGameInfoResponse>('GET_GAME_INFO', { game_code: gameCode, currency });
        return frame.payload!;
    }

    async spin(gameCode: string, betAmount: string, buyFeature: boolean = false, correlationId?: string): Promise<SlotApiSpinResponse> {
        const frame = await this.request<SlotApiSpinResponse>('SLOT_SPIN', { game_code: gameCode, bet_amount: betAmount, buy_feature: buyFeature }, correlationId);
        return frame.payload!;
    }

    async getBetHistory(gameCode: string, limit: number = 20, cursor: string = ''): Promise<SlotApiBetHistoryResponse> {
        const payload: SlotApiBetHistoryRequest = { limit, cursor, game_code: gameCode };
        const frame = await this.request<SlotApiBetHistoryResponse>('GET_BET_HISTORY', payload);
        return frame.payload!;
    }

    async getBetDetail(operationId: string): Promise<SlotApiBetDetailResponse> {
        const payload: SlotApiBetDetailRequest = { operation_id: operationId };
        const frame = await this.request<SlotApiBetDetailResponse>('GET_BET_DETAIL', payload);
        return frame.payload!;
    }

    /** Jackpot pool 未訂閱不會再收到更新 */
    async getJackpotPool(gameCode: string): Promise<SlotApiJackpotPoolSnapshot> {
        const payload: SlotApiJackpotPoolRequest = { game_code: gameCode };
        const frame = await this.request<SlotApiJackpotPoolSnapshot>('GET_JACKPOT_POOL', payload);
        return frame.payload!;
    }

    /**
     * 訂閱 Jackpot pool
     * 以 correlation_id 為依據的 JACKPOT_POOL_UPDATE 由 GameNetHandler 處理
     */
    async subscribeJackpotPool(gameCode: string): Promise<SlotApiJackpotPoolSnapshot> {
        const payload: SlotApiJackpotPoolRequest = { game_code: gameCode };
        const frame = await this.request<SlotApiJackpotPoolSnapshot>('SUBSCRIBE_JACKPOT_POOL', payload);
        return frame.payload!;
    }

    async unsubscribeJackpotPool(gameCode: string): Promise<SlotApiJackpotUnsubscribeResponse> {
        const payload: SlotApiJackpotPoolRequest = { game_code: gameCode };
        const frame = await this.request<SlotApiJackpotUnsubscribeResponse>('UNSUBSCRIBE_JACKPOT_POOL', payload);
        return frame.payload!;
    }

    async getGameState(gameCode: string, tableId?: string): Promise<SlotApiGameStateResponse> {
        const frame = await this.request<SlotApiGameStateResponse>('GET_GAME_STATE', { game_code: gameCode, table_id: tableId ?? '' });
        return frame.payload!;
    }

    async request<TPayload = unknown>(type: SlotApiRequestType, payload?: unknown, correlationId: string = this.createCorrelationId(type)): Promise<SlotApiFrame<TPayload>> {
        await this.connect();
        const frame: SlotApiFrame = { type, correlation_id: correlationId, ts_ms: Date.now() };
        if (payload !== undefined) frame.payload = payload;

        return new Promise<SlotApiFrame<TPayload>>((resolve, reject) => {
            const timeoutId = setTimeout(() => {
                this.pending.delete(correlationId);
                reject(new Error(`slot websocket request timeout: ${type}`));
            }, this.requestTimeoutMs);

            this.pending.set(correlationId, {
                resolve: resolve as (frame: SlotApiFrame<any>) => void,
                reject,
                timeoutId,
            });
            try {
                console.log('[SlotWSClient][Request]', frame);
                this.socket!.send(JSON.stringify(frame));
            } catch (error) {
                clearTimeout(timeoutId);
                this.pending.delete(correlationId);
                reject(error instanceof Error ? error : new Error(String(error)));
            }
        });
    }

    private handleMessage(rawData: unknown): void {
        if (typeof rawData !== 'string') return;

        let frame: SlotApiFrame;
        try {
            frame = JSON.parse(rawData) as SlotApiFrame;
        } catch {
            return;
        }

        console.log('[SlotWSClient][Response]', frame);
        const correlationId = frame.correlation_id;
        const pending = correlationId ? this.pending.get(correlationId) : undefined;
        if (pending && correlationId) {
            clearTimeout(pending.timeoutId);
            this.pending.delete(correlationId);
        }

        // ACK 直接拒絕原請求
        if (frame.type === SLOT_API_RESPONSE_TYPE.ACK && frame.error) {
            pending?.reject(new Error(`${frame.error.code}: ${frame.error.message}`));
            return;
        }

        // Handler 錯誤回到原請求
        try {
            for (const listener of this.listeners) listener(frame);
        } catch (error) {
            const handlerError = error instanceof Error ? error : new Error(String(error));
            if (pending) pending.reject(handlerError);
            else console.error('[SlotWSClient][HandlerError]', handlerError);
            return;
        }

        pending?.resolve(frame);
    }

    private rejectPending(message: string): void {
        for (const [correlationId, pending] of this.pending) {
            clearTimeout(pending.timeoutId);
            pending.reject(new Error(message));
            this.pending.delete(correlationId);
        }
    }

    private startHeartbeat(): void {
        this.stopHeartbeat();
        if (this.heartbeatIntervalMs <= 0) return;
        this.heartbeatId = setInterval(() => {
            if (this.isOpen) this.ping().catch(() => undefined);
        }, this.heartbeatIntervalMs);
    }

    private stopHeartbeat(): void {
        if (!this.heartbeatId) return;
        clearInterval(this.heartbeatId);
        this.heartbeatId = null;
    }

    private createCorrelationId(type: string): string {
        const cryptoRef = globalThis.crypto as Crypto | undefined;
        const randomId = cryptoRef?.randomUUID?.() ?? Math.random().toString(36).slice(2);
        return `${type.toLowerCase()}-${Date.now()}-${randomId}`;
    }
}
