import { _decorator, Component, director, Node, sp } from "cc";
import AppAudio from "../audio/AppAudio";
import { EFFECTSMAP } from '../audio/AudioConfig';
import StoreManager from "../store/StoreManager";
import { GameViewAdapter } from "./GameViewAdapter";
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from "../events/GameRuntimeEventBus";

const { ccclass, property } = _decorator;

@ccclass("1002/HsTransitionView")
export class HsTransitionView extends Component {

    @property(sp.Skeleton)
    spine: sp.Skeleton = null!;

    private _disposeReaction: (() => void) | null = null;
    private _disposeOrientation: (() => void) | null = null;
    private resolveClose: (() => void) | null = null;
    private dismissed: boolean = false;
    private autoTimer: number = 0;
    private currentBasePrefix: string = '';
    private currentPrefix: string = '';

    protected override onLoad(): void {
        this.node.on(Node.EventType.TOUCH_START, this.onTouchStart, this);
        const gameStore = StoreManager.getInstance().getGameStore();
        // mobx 移除計劃：SlotGameStore.hsTransitionData 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this._disposeReaction = gameRuntimeEventBus.on(GAME_EVENT_TYPE.HS_TRANSITION_DATA_CHANGED, (e) => {
            if (e.data) this.show(e.data.basePrefix).then(() => gameStore.completeHsTransition());
        });
        // mobx 移除計劃：DeviceStore.orientation 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this._disposeOrientation = gameRuntimeEventBus.on(
            GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED,
            () => this.refreshOrientation()
        );
        const data = gameStore.hsTransitionData;
        if (data) this.show(data.basePrefix).then(() => gameStore.completeHsTransition());
    }

    private resolveFullPrefix(basePrefix: string): string {
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const adapter = director.getScene()?.getComponentsInChildren(GameViewAdapter)
            .find(a => a.node.name === adapterName);
        const adapterPrefix = adapter?.hsTransitionAnimPrefix ?? '';
        return adapterPrefix + basePrefix;
    }

    private refreshOrientation(): void {
        if (!this.currentBasePrefix || this.dismissed || !this.node?.isValid) return;
        this.currentPrefix = this.resolveFullPrefix(this.currentBasePrefix);
        this.spine.setCompleteListener(null!);
        this.spine.setAnimation(0, `${this.currentPrefix}_待機`, true);
    }

    show(basePrefix: string): Promise<void> {
        this.currentBasePrefix = basePrefix;
        this.currentPrefix = this.resolveFullPrefix(basePrefix);

        this.dismissed = false;
        if (this.node?.isValid) this.node.active = true;
        AppAudio.getInstance().playEffect(EFFECTSMAP.BONUS_IN);

        return new Promise<void>(resolve => {
            this.resolveClose = resolve;
            try {
                this.spine.setAnimation(0, `${this.currentPrefix}_出現`, false);
                this.spine.setCompleteListener(() => {
                    this.spine.setCompleteListener(null!);
                    if (!this.node?.isValid) return;
                    this.spine.setAnimation(0, `${this.currentPrefix}_待機`, true);
                });
            } catch (e) { }
            this.autoTimer = setTimeout(() => this.dismiss(), 5000) as unknown as number;
        });
    }

    private onTouchStart(): void { this.dismiss(); }

    private dismiss(): void {
        if (this.dismissed) return;
        this.dismissed = true;
        if (this.autoTimer) { clearTimeout(this.autoTimer); this.autoTimer = 0; }
        AppAudio.getInstance().playEffect(EFFECTSMAP.BONUS_CLOSE);
        const safety = setTimeout(() => this.close(), 1500);
        try {
            this.spine.setAnimation(0, `${this.currentPrefix}_退場`, false);
            this.spine.setCompleteListener(() => {
                clearTimeout(safety);
                this.spine.setCompleteListener(null!);
                this.close();
            });
        } catch (e) {
            clearTimeout(safety);
            this.close();
        }
    }

    private close(): void {
        if (this.node?.isValid) this.node.active = false;
        AppAudio.getInstance().stopLoopEffect(EFFECTSMAP.BONUS_LOOP);
        this.resolveClose?.();
        this.resolveClose = null;
    }

    protected override onDestroy(): void {
        this._disposeReaction?.();
        this._disposeReaction = null;
        this._disposeOrientation?.();
        this._disposeOrientation = null;
        if (this.autoTimer) { clearTimeout(this.autoTimer); this.autoTimer = 0; }
        this.node?.off(Node.EventType.TOUCH_START, this.onTouchStart, this);
    }
}
